import React from 'react';
const XemHoaDon = () => (
    <div style={{backgroundColor: '#fff', padding: '25px', borderRadius: '15px'}}>
        <h2 style={{marginBottom: '20px'}}>📄 Hóa đơn dịch vụ tháng 04/2026</h2>
        <table style={{width: '100%', borderCollapse: 'collapse'}}>
            <thead style={{backgroundColor: '#f8f9fa', textAlign: 'left'}}>
                <tr><th style={{padding: '15px'}}>Loại phí</th><th>Kỳ hạn</th><th>Số tiền</th><th>Trạng thái</th></tr>
            </thead>
            <tbody>
                <tr style={{borderBottom: '1px solid #eee'}}><td style={{padding: '15px'}}>Tiền điện</td><td>20/04/2026</td><td>1,200,000đ</td><td style={{color: 'red'}}>Chưa thanh toán</td></tr>
                <tr style={{borderBottom: '1px solid #eee'}}><td style={{padding: '15px'}}>Phí quản lý</td><td>15/04/2026</td><td>500,000đ</td><td style={{color: 'green'}}>Đã thanh toán</td></tr>
            </tbody>
        </table>
    </div>
);
export default XemHoaDon;
